/*
 * A059769  Frobenius number of the subsemigroup of the natural numbers
 *          generated by successive pairs of Fibonacci numbers.
 * https://oeis.org/A059769
 *
 * Offset:    3    (a(3) is the first term)
 * Keywords:  nonn, easy
 * Formula:   a(n) = F(n)*F(n+1) - F(n+2) (offset 3)
 * Range:     u8 n <= 7, u16 n <= 12, u32 n <= 24, u64 n <= 47, u128 n <= 93,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* This implementation lazily builds the Fibonacci sequence in a static array. */
#include <stdlib.h>

seq_t a(idx_t n)
{
    /* static cache of Fibonacci numbers */
    static seq_t *fib = NULL;
    static idx_t fibsize = 0;   /* number of values stored */

    /* initialise cache with F(0) = 0, F(1) = 1 */
    if (fibsize < 2) {
        fibsize = 2;
        fib = (seq_t *)malloc(fibsize * sizeof(seq_t));
        if (!fib) return (seq_t)0;          /* allocation failure: return 0 */
        fib[0] = (seq_t)0;
        fib[1] = (seq_t)1;
    }

    /* we need F(n), F(n+1), and F(n+2) -> allocate up to index n+2 */
    idx_t needed = n + 3;   /* because array is 0‑based and we need index n+2 */
    if (needed > fibsize) {
        idx_t newsize = needed;
        seq_t *tmp = (seq_t *)realloc(fib, newsize * sizeof(seq_t));
        if (!tmp) return (seq_t)0;          /* allocation failure: return 0 */
        fib = tmp;
        for (idx_t i = fibsize; i < newsize; ++i)
            fib[i] = fib[i - 1] + fib[i - 2];
        fibsize = newsize;
    }

    /* compute a(n) = F(n)*F(n+1) - F(n+2) */
    seq_t fn   = fib[(size_t)n];
    seq_t fn1  = fib[(size_t)n + 1];
    seq_t fn2  = fib[(size_t)n + 2];

    return fn * fn1 - fn2;
}
